#!/usr/bin/env node
/**
 * Clear Next's generated route types before the generated files can be checked
 * against a route tree that has moved on.
 *
 * Two ways this goes wrong, both of them dead ends that name files nobody
 * edited:
 *
 * 1. **Stale route types.** `.next/types` is generated. Add or delete a route
 *    without a `next build` or a `next dev` in between and it still describes
 *    the old tree — `npm run typecheck` then fails inside `.next/types` for a
 *    page that no longer exists (or is missing one that does), and because
 *    `npm run build` checks types in `prebuild`, the build fails before it
 *    could have regenerated them. `prebuild` runs this so a build is never
 *    blocked by its own generated output.
 * 2. **Two toolchains, one filename.** Both `next build` and `vinext build`
 *    claim `.next/types/routes.d.ts`, and they write different
 *    things into it:
 *
 *   - `next build` writes the route-map module that its own generated
 *     `.next/types/validator.ts` imports (`AppRoutes`, `LayoutRoutes`, `ParamMap`,
 *     `AppRouteHandlerRoutes`) — this is what type-checks every page, layout and
 *     route handler against its real params.
 *   - `vinext build` writes global `PageProps`/`LayoutProps`/`RouteContext`
 *     declarations for the same file, with none of those exports.
 *
 *    Run vinext after a Next build and the two disagree: `validator.ts` imports
 *    exports that no longer exist. Clearing first leaves Next's `validator.ts`
 *    out of the picture entirely; `next build` writes it back on the next Next
 *    build, when the pair is consistent again.
 *
 * Only the type directory is touched. `.next` itself holds the running preview
 * server's assets and must not be deleted out from under it.
 */
import fs from 'node:fs';
import path from 'node:path';

const types = path.join(process.cwd(), '.next', 'types');

if (fs.existsSync(types)) {
  fs.rmSync(types, { recursive: true, force: true });
  console.log('Removed .next/types (regenerated by the next `next build`).');
}
